def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    if n >= 5:
        opp_def = sum(1 for a, b in history if b == 'D')
        if opp_def > n * 0.8:
            return 'D'

    last_me, last_opp = history[-1]

    retaliations = 0
    probes = 0
    for i in range(n):
        a, b = history[i]
        if a == 'D' and b == 'C':
            probes += 1
        if i < n - 1:
            _, next_opp = history[i + 1]
            if a == 'D' and next_opp == 'D':
                retaliations += 1

    if retaliations > 0:
        if last_opp == 'D':
            if last_me == 'D':
                return 'C' if rng.random() < 0.7 else 'D'
            else:
                return 'D' if rng.random() < 0.5 else 'C'
        else:
            if last_me == 'D':
                return 'C'
            return 'C'
    else:
        if last_opp == 'D':
            if last_me == 'D':
                return 'C'
            else:
                return 'D' if rng.random() < 0.5 else 'C'
        else:
            if last_me == 'D':
                return 'C'
            if probes < 2:
                interval = 10
            elif probes < 5:
                interval = 5
            elif probes < 8:
                interval = 3
            else:
                if rng.random() < 0.9:
                    return 'D'
                return 'C'
            if n % interval == 0:
                return 'D'
            return 'C'
